package com.projeto.sonia.controller; import com.projeto.sonia.model.Usuario; import com.projeto.sonia.repository.UsuarioRepository; import jakarta.servlet.http.HttpSession; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/auth") public class UsuarioController {private final UsuarioRepository repo;private final PasswordEncoder encoder;public UsuarioController(UsuarioRepository r,PasswordEncoder e){repo=r;encoder=e;} @PostMapping("/cadastro") public ResponseEntity<String> cadastro(@RequestBody Map<String,String>d){String email=d.get("email").trim().toLowerCase();if(repo.existsByEmail(email))return ResponseEntity.status(409).body("E-mail já cadastrado.");Usuario u=new Usuario();u.setNome(d.get("nome").trim());u.setEmail(email);u.setSenha(encoder.encode(d.get("senha")));repo.save(u);return ResponseEntity.status(201).body("Cadastro realizado com sucesso.");} @PostMapping("/login") public ResponseEntity<String> login(@RequestBody Map<String,String>d,HttpSession s){Usuario u=repo.findByEmail(d.get("email").trim().toLowerCase()).orElse(null);if(u==null||!encoder.matches(d.get("senha"),u.getSenha()))return ResponseEntity.status(401).body("E-mail ou senha incorretos.");s.setAttribute("usuarioId",u.getId());return ResponseEntity.ok("Login realizado com sucesso.");}}